create table if not exists public.cele_settings(user_id uuid primary key references auth.users(id) on delete cascade,target_exam_date date,daily_target_minutes integer not null default 60,study_days smallint[] not null default '{1,2,3,4,5,6}',rest_days smallint[] not null default '{0}',confidence jsonb not null default '{"structural":"okay","mste":"okay","hge":"okay"}'::jsonb,reminder_enabled boolean not null default true,reminder_time time not null default '19:00',onboarding_completed boolean not null default false,updated_at timestamptz not null default now());alter table public.cele_settings enable row level security;create policy "cele_settings_own" on public.cele_settings for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
